return items.map(item => {
  const body = item.json.body || {};

  const numeroOriginal = body.contato || "";
  const numeroLimpo = numeroOriginal.replace(/[^0-9]/g, "");

  const dataOriginal = body.Data || ""; // YYYY-MM-DD
  let dataFormatada = "";

  if (dataOriginal) {
    const [ano, mes, dia] = dataOriginal.split("-");
    dataFormatada = `${dia}-${mes}-${ano}`;
  }

  return {
    json: {
      ...item.json,
      body: {
        ...body,
        telefoneFormatado: numeroLimpo,
        Data: dataFormatada
      }
    }
  };
});

